    }

    # Goal state
    goal_state = {
        'on_table': {'blue', 'green', 'yellow'},
        'clear': {'cyan', 'black'},
        'on_top_of': {'red': 'purple', 'white': 'magenta', 'cyan': 'white', 'yellow': 'brown', 'orange': 'green', 'brown': 'red', 'black': 'yellow'}
    }

