def get_block_status(table, stacks, holding):
    status = {}
    for block in table:
        status[block] = {'location': 'table', 'clear': True}
    for top, bottom in stacks:
        status[top] = {'location': 'on', 'on': bottom}
        status[bottom] = status.get(bottom, {'location': 'table', 'clear': False})
        status[bottom]['clear'] = False
    for block in status:
        if status[block]['location'] == 'on':
            status[block]['clear'] = True
    for top, bottom in stacks:
        if status[bottom]['clear']:
            status[bottom]['clear'] = False
    for block in holding:
        status[block] = {'location': 'holding'}
    return status

