    return block_name

def is_clear(block, blocks):
    for other_block in blocks:
        if blocks[other_block] == block:
            return False
    return True

def find_on_top_of(block, blocks):
    for other_block in blocks:
        if block == blocks[other_block]:
            return other_block
    return None

def find_top_block(block, blocks):
    top = block
    while find_on_top_of(top, blocks) is not None:
        top = find_on_top_of(top, blocks)
    return top

